package com.bank.intern;

import java.util.logging.*;

public class StringInternDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String literal = "SAV2001";
        String fromDb  = new String("SAV2001"); // distinct heap object
        String interned = fromDb.intern();       // pooled reference

        // == compares IDENTITY (same object); .equals compares VALUE.
        log.warning(() -> "literal == fromDb   : " + (literal == fromDb));    // false
        log.info(() -> "literal .equals fromDb : " + literal.equals(fromDb)); // true
        log.info(() -> "literal == interned    : " + (literal == interned));  // true

        // Deliberate interning of a bounded set enables fast == on status codes.
        StatusCodes codes = new StatusCodes();
        String s1 = codes.canonical(new String("COMPLETED"));
        String s2 = codes.canonical(new String("COMPLETED"));
        log.info(() -> "canonical status == : " + (s1 == s2)); // true (both pooled)
        log.info(() -> "is COMPLETED (fast==): " + (s1 == "COMPLETED")); // true
    }
}

// ─── Would be StatusCodes.java in a real project ───
class StatusCodes {
    // Bounded, known values -> safe to intern for fast identity comparison.
    String canonical(String raw) {
        return raw.intern();
    }
}
